/** Site-wide constants. */
export const SITE_NAME = 'PML Home';
export const SITE_CITY = 'Quy Nhơn';

/** Share image for pages without a room photo (generated by `npm run icons`). */
export const DEFAULT_SHARE_IMAGE = { src: '/og-default.jpg', width: 1200, height: 630 } as const;

/**
 * Landlord entry points (header, footer, home CTA). Signed in: "Đăng phòng"
 * opens the new-room form. Signed out: "Cho thuê phòng" opens sign-up (which
 * links to sign-in), and both come back to the new-room form afterwards.
 */
export const LANDLORD_START_PATH = '/quan-ly/phong/moi';
export const LANDLORD_SIGN_UP_PATH = `/dang-ky?next=${encodeURIComponent(LANDLORD_START_PATH)}`;
export const LANDLORD_SIGN_IN_PATH = `/dang-nhap?next=${encodeURIComponent(LANDLORD_START_PATH)}`;

/** Map center when no room has a location yet (Quy Nhơn city center). */
export const SITE_MAP_CENTER = { lat: 13.7765, lng: 109.2237 };
